def _wait_for(self, callback, timeout=None):
        """
        Spins until callback() returns truthy.
        """
        start = time.time()
        while not callback():
            if timeout is not None and time.time() - start > timeout:
                raise TimeoutError("Timed out waiting for {}".format(callback))
            time.sleep(0.01)

